func decodeRouteResult[T any](r Result, route RouteID) (T, error) {
	var zero T
	if r.R0 != 0 || r.R1 != 0 {
		return zero, invalidRouteResult(route)
	}
	if err, ok := r.Value.(error); ok {
		if r.Errno != 0 {
			return zero, invalidRouteResult(route)
		}
		return zero, err
	}
	if r.Errno != 0 {
		if r.Value != nil {
			return zero, invalidRouteResult(route)
		}
		return zero, syscall.Errno(r.Errno)
	}
	value, ok := r.Value.(T)
	if !ok {
		return zero, invalidRouteResult(route)
	}
	return value, nil
}

func invalidRouteResult(route RouteID) error {
	return &contracts.Failure{Code: contracts.InvalidABI, Diagnostic: contracts.Diagnostic{Operation: "result-decode", Message: fmt.Sprintf("invalid typed result for route %d", route)}}
}

